  { title: "Heard 'Em Say", album: "Late Orchestration", match: "", file: "7. Heard 'Em Say - Live At Abbey Road Studios.mp3" },
  { title: "LIFT YOURSELF", album: "Library", match: "", file: "7. LIFT YOURSELF.mp3" },
  { title: "Maybe", album: "Vultures 2", match: "", file: "7. Maybe.mp3" },
  { title: "SEE ME AGAIN", album: "Library", match: "", file: "7. SEE ME AGAIN.mp3" },
  { title: "All Falls Down", album: "Late Orchestration", match: "", file: "8. All Falls Down - Live At Abbey Road Studios.mp3" },
  { title: "Fortune And Fame", album: "Vultures 2", match: "", file: "8. Fortune And Fame.mp3" },
  { title: "Bring Me Down", album: "Late Orchestration", match: "", file: "9. Bring Me Down - Live At Abbey Road Studios.mp3" },
  { title: "Thirsty", album: "Vultures 2", match: "", file: "9. Thirsty.mp3" },
  { title: "Can't Hurry Love [V2]", album: "Misc", match: "", file: "CAN'T HURRY LOVE (I CAN'T WAIT) [V2].mp3" },
  { title: "Can't Hurry Love", album: "Misc", match: "", file: "CAN'T HURRY LOVE (I CAN'T WAIT).mp3" },
  { title: "Chanel x Come To Life", album: "Misc", match: "", file: "Chanel x Come To Life.mp3" },
  { title: "CyHi - The G.O.O.D Ole Days", album: "Misc", match: "", file: "CyHi - The G.O.O.D Ole Days.mp3" },
  { title: "Flashing Lights [Remix]", album: "Misc", match: "", file: "Flashing Lights [Remix] [Beat].wav" },
  { title: "Frank Ocean - Wise Man", album: "Misc", match: "", file: "Frank Ocean - Wise Man.mp3" },
  { title: "Freeze The World", album: "Misc", match: "", file: "Freeze The World.mp3" },
  { title: "I MISS YE", album: "Misc", match: "", file: "I MISS YE.mp3" },
  { title: "Montell Jordan - Daddy's Home", album: "Misc", match: "", file: "Montell Jordan - Daddy's Home.flac" },
  { title: "Runaway (Free Larry Hoover)", album: "Misc", match: "", file: "Runaway (Free Larry Hoover Benefit Concert) [Mike Dean Mix].mp3" },
  { title: "Runaway Outro Snippet", album: "Misc", match: "", file: "Runaway Outro Snippet.wav" },
  { title: "Snow On Tha Bluff", album: "Misc", match: "", file: "Snow On Tha Bluff (w- chords).wav" },
  { title: "Spread Your Wings", album: "Misc", match: "", file: "Spread Your Wings.mp3" },
  { title: "Violent Crimes", album: "Misc", match: "", file: "Violent Crimes.wav" },
];
let tracks = [];
let current = -1;
let audio = null;
let isPlaying = false;
let volume = 0.75;


const coverCache = {};
const defaultCover = document.getElementById("coverImg").getAttribute("href") || document.getElementById("coverImg").getAttributeNS("http://www.w3.org/1999/xlink", "href");

function setCover(url) {
  const img = document.getElementById("coverImg");
  if (!img || !url) return;
  img.setAttribute("href", url);
  img.setAttributeNS("http://www.w3.org/1999/xlink", "href", url);
}

function decodeId3Text(frame) {
  if (!frame || !frame.length) return "";
  const enc = frame[0];
  let data = frame.subarray(1);
  let text = "";
  try {
    if (enc === 0) text = new TextDecoder("latin1").decode(data);
    else if (enc === 1) text = new TextDecoder("utf-16").decode(data);
    else if (enc === 2) text = new TextDecoder("utf-16be").decode(data);
    else text = new TextDecoder("utf-8").decode(data);
  } catch (e) {
    text = new TextDecoder("latin1").decode(data);
  }
  return text.replace(/\u0000/g, "").trim();
}

function parseId3(buf) {
  const data = new Uint8Array(buf);
  if (data.length < 10 || String.fromCharCode(data[0], data[1], data[2]) !== "ID3") return null;
  const ver = data[3];
  const tagSize = (data[6]<<21)|(data[7]<<14)|(data[8]<<7)|data[9];
  const out = { title:"", album:"", artist:"", picture:null, mime:"" };
  let i = 10;
  const end = Math.min(data.length, 10 + tagSize);
  while (i + 10 <= end) {
    const id = String.fromCharCode(data[i], data[i+1], data[i+2], data[i+3]);
    if (id === "\u0000\u0000\u0000\u0000" || !data[i]) break;
    const fsize = ver >= 4
      ? ((data[i+4]<<21)|(data[i+5]<<14)|(data[i+6]<<7)|data[i+7])
      : ((data[i+4]<<24)|(data[i+5]<<16)|(data[i+6]<<8)|data[i+7]);
    i += 10;
    if (fsize <= 0 || i + fsize > data.length) break;
    const frame = data.subarray(i, i + fsize);
    i += fsize;
    if (id === "TIT2") out.title = decodeId3Text(frame);
    else if (id === "TALB") out.album = decodeId3Text(frame);
    else if (id === "TPE1") out.artist = decodeId3Text(frame);
    else if (id === "APIC" && !out.picture) {
      let p = 1;
      let mime = "";
      while (p < frame.length && frame[p] !== 0) { mime += String.fromCharCode(frame[p]); p++; }
      p += 2; // null + picture type
      const enc = frame[0];
      if (enc === 1 || enc === 2) { while (p + 1 < frame.length && !(frame[p]===0 && frame[p+1]===0)) p++; p += 2; }
      else { while (p < frame.length && frame[p] !== 0) p++; p += 1; }
      if (p < frame.length) {
        out.picture = frame.subarray(p);
        out.mime = mime || "image/jpeg";
      }
    }
  }
  out.tagSize = tagSize;
  return out;
}

async function readTags(url, full) {
  const head = await fetch(url, { headers: { Range: "bytes=0-9" } });
  if (!head.ok && head.status !== 206) return null;
  const hb = new Uint8Array(await head.arrayBuffer());
  if (hb.length < 10 || String.fromCharCode(hb[0], hb[1], hb[2]) !== "ID3") return null;
  const tagSize = ((hb[6]<<21)|(hb[7]<<14)|(hb[8]<<7)|hb[9]) + 10;
  const want = full ? tagSize : Math.min(tagSize, 120000);
  const res = await fetch(url, { headers: { Range: "bytes=0-" + (want - 1) } });
  if (!res.ok && res.status !== 206) return null;
  return parseId3(await res.arrayBuffer());
}

async function applyTags(track, idx, full) {
  if (!track || !track.url || track.url.startsWith("blob:")) return;
  try {
    const tags = await readTags(track.url, !!full);
    if (!tags) return;
    if (tags.title) track.title = tags.title;
    if (tags.album) track.album = tags.album;
    if (tags.artist) track.artist = tags.artist;
    if (tags.album && tags.picture && tags.picture.length > 500) {
      const blob = new Blob([tags.picture], { type: tags.mime || "image/jpeg" });
      coverCache[tags.album] = URL.createObjectURL(blob);
    }
    if (idx === current) {
      updateUI();
      if (track.album && coverCache[track.album]) setCover(coverCache[track.album]);
    }
    const row = document.querySelectorAll(".track-item")[idx];
    if (row) {
      const albumSpan = row.querySelector(".album-label");
      if (albumSpan && track.album) albumSpan.textContent = track.album;
      const titleSpan = row.querySelector(".title-label");
      if (titleSpan && track.title) titleSpan.textContent = track.title;
    }
  } catch (e) {}
}

function formatTime(s) {
  if (!isFinite(s) || isNaN(s)) return "0:00";
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return m + ":" + (sec < 10 ? "0" : "") + sec;
}

function updateUI() {
  const t = tracks[current];
  if (!t) return;
  document.getElementById("trackTitle").textContent = t.title;
  document.getElementById("trackAlbum").textContent = t.artist ? (t.album + " · " + t.artist) : t.album;
  const items = document.querySelectorAll(".track-item");
  items.forEach((el, i) => {
    el.style.background = i === current ? "#1f1a0a" : "transparent";
    el.style.color = i === current ? "#c9a227" : "#ddd";
  });
}

function loadTrack(idx) {
  if (idx < 0 || idx >= tracks.length) return;
  current = idx;
  if (audio) { audio.pause(); audio = null; }
  const t = tracks[idx];
  audio = new Audio(t.url);
  audio.volume = volume;
  const paintProgress = () => {
    if (!audio) return;
    const dur = audio.duration;
    const pct = (dur && isFinite(dur)) ? (audio.currentTime / dur) : 0;
    document.getElementById("progressFill").setAttribute("width", Math.max(0, 580 * pct));
    document.getElementById("progressKnob").setAttribute("cx", 280 + 580 * pct);
    document.getElementById("trackTime").textContent = formatTime(audio.currentTime) + " / " + formatTime(dur);
  };
  audio.addEventListener("timeupdate", paintProgress);
  audio.addEventListener("loadedmetadata", paintProgress);
  audio.addEventListener("durationchange", paintProgress);
  audio.addEventListener("progress", paintProgress);
  audio.volume = volume;
  audio.addEventListener("ended", () => nextTrack());
  audio.addEventListener("error", () => {
    document.getElementById("trackTitle").textContent = "Failed to load: " + t.title;
    document.getElementById("trackAlbum").textContent = t.url;
  });
  updateUI();
  if (t.album && coverCache[t.album]) setCover(coverCache[t.album]);
  else if (!t.album || t.album === "Library" || t.album === "Misc") setCover(defaultCover);
  applyTags(t, idx, true);
  if (isPlaying) audio.play().catch(()=>{});
}

function togglePlay() {
  if (tracks.length === 0) {
    document.getElementById("trackTitle").textContent = "Load tracks first (URL or drop)";
    return;
  }
  if (current < 0) { loadTrack(0); isPlaying = true; }
  if (!audio) return;
  if (isPlaying) {
    audio.pause(); isPlaying = false;
    document.getElementById("playIcon").style.display = "block";
    document.getElementById("pauseIcon").style.display = "none";
  } else {
    audio.play().catch(()=>{}); isPlaying = true;
    document.getElementById("playIcon").style.display = "none";
    document.getElementById("pauseIcon").style.display = "block";
  }
}

function nextTrack() {
  if (!tracks.length) return;
  loadTrack((current + 1) % tracks.length);
  isPlaying = true;
  document.getElementById("playIcon").style.display = "none";
  document.getElementById("pauseIcon").style.display = "block";
  if (audio) audio.play().catch(()=>{});
}

function prevTrack() {
  if (!tracks.length) return;
  loadTrack(current <= 0 ? tracks.length - 1 : current - 1);
  isPlaying = true;
  document.getElementById("playIcon").style.display = "none";
  document.getElementById("pauseIcon").style.display = "block";
  if (audio) audio.play().catch(()=>{});
}

function playTrack(idx) {
  isPlaying = true;
  loadTrack(idx);
  document.getElementById("playIcon").style.display = "none";
  document.getElementById("pauseIcon").style.display = "block";
  if (audio) audio.play().catch(()=>{});
}

function rebuildPlaylist() {
  const list = document.getElementById("playlist");
  list.innerHTML = "";
  document.getElementById("playlistCount").textContent = tracks.length + " tracks";
  tracks.forEach((t, i) => {
    const div = document.createElement("div");
    div.className = "track-item";
    div.style.cssText = "padding:8px 10px; margin:2px 0; border-radius:6px; cursor:pointer; display:flex; justify-content:space-between;";
    div.innerHTML = `<span><span style="color:#666;margin-right:10px;width:24px;display:inline-block">${String(i+1).padStart(2,"0")}</span><span class="title-label">${t.title}</span></span><span class="album-label" style="color:#555;font-size:11px;max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-left:8px">${t.album}</span>`;
    div.onmouseover = () => { if (i !== current) div.style.background = "#1a1a1a"; };
    div.onmouseout  = () => { if (i !== current) div.style.background = "transparent"; };
    div.onclick = () => playTrack(i);
    list.appendChild(div);
  });
}

// ---------- Remote (Base URL) mode ----------
function loadFromBaseURL(url) {
  BASE_URL = url.trim();
  if (!BASE_URL.endsWith("/")) BASE_URL += "/";
  tracks = trackMeta.map(m => ({
    title: m.title,
    album: m.album,
    url: BASE_URL + encodeURIComponent(m.file).replace(/%20/g, "%20"),
    file: m.file
  }));
  // also try without encoding for servers that hate it
  rebuildPlaylist();
  document.getElementById("trackTitle").textContent = tracks.length + " tracks from server";
  document.getElementById("trackAlbum").textContent = "Reading album tags…";
  (async () => {
    for (let i = 0; i < tracks.length; i++) await applyTags(tracks[i], i, false);
  })();
  document.getElementById("dropZone").style.display = "none";
  document.getElementById("urlBar").style.display = "none";
}

// ---------- Local drag-and-drop fallback ----------
function addFiles(fileList) {
  const audioFiles = Array.from(fileList).filter(f =>
    f.type.startsWith("audio/") || /\.(mp3|wav|ogg|m4a|flac|aac)$/i.test(f.name)
  );
  if (!audioFiles.length) {
    document.getElementById("trackTitle").textContent = "No audio files found";
    return;
  }
  tracks = [];
  audioFiles.forEach(file => {
    const meta = trackMeta.find(m => file.name.toLowerCase().includes(m.match)) ||
                 { title: file.name.replace(/\.(mp3|wav|ogg|m4a)$/i,""), album: "Loaded" };
    tracks.push({
      title: meta.title,
      album: meta.album,
      url: URL.createObjectURL(file),
      file: file.name
    });
  });
  tracks.sort((a,b) => a.file.localeCompare(b.file, undefined, {numeric:true}));
  rebuildPlaylist();
  document.getElementById("trackTitle").textContent = tracks.length + " tracks loaded locally";
  document.getElementById("trackAlbum").textContent = "Ready to play";
  document.getElementById("dropZone").style.display = "none";
  document.getElementById("urlBar").style.display = "none";
}

function init() {
  // URL bar submit
  const goBtn = document.getElementById("goBtn");
  const urlInput = document.getElementById("baseUrlInput");
  if (goBtn) {
    goBtn.onclick = () => {
      const v = urlInput.value.trim();
      if (v) loadFromBaseURL(v);
    };
    urlInput.addEventListener("keydown", e => {
      if (e.key === "Enter") goBtn.onclick();
    });
  }

  // Drop zone
  const zone = document.getElementById("dropZone");
  const svg = document.documentElement;
  ["dragenter","dragover","dragleave","drop"].forEach(ev => {
    svg.addEventListener(ev, e => { e.preventDefault(); e.stopPropagation(); });
  });
  zone.addEventListener("dragover", () => zone.style.borderColor = "#c9a227");
  zone.addEventListener("dragleave", () => zone.style.borderColor = "#444");
  zone.addEventListener("drop", e => {
    zone.style.borderColor = "#444";
    addFiles(e.dataTransfer.files);
  });
  zone.addEventListener("click", () => {
    const input = document.createElement("input");
    input.type = "file"; input.multiple = true;
    input.accept = "audio/*,.mp3,.wav,.ogg,.m4a,.flac";
    input.onchange = () => addFiles(input.files);
    input.click();
  });
}

window.togglePlay = togglePlay;
window.nextTrack = nextTrack;
window.prevTrack = prevTrack;
window.playTrack = playTrack;


function paintVolume() {
  const w = 80 * volume;
  const fill = document.getElementById("volFill");
  const knob = document.getElementById("volKnob");
  if (fill) fill.setAttribute("width", w);
  if (knob) knob.setAttribute("cx", 235 + w);
  if (audio) audio.volume = volume;
}

function ratioFrom(el, e) {
  const r = el.getBoundingClientRect();
  if (!r.width) return 0;
  return Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
}

function bindDrag(el, measureEl, onRatio) {
  if (!el) return;
  const box = measureEl || el;
  el.addEventListener("pointerdown", e => {
    e.preventDefault();
    e.stopPropagation();
    try { el.setPointerCapture(e.pointerId); } catch (err) {}
    onRatio(ratioFrom(box, e));
    const move = ev => onRatio(ratioFrom(box, ev));
    const up = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  });
}

function bindSliders() {
  const progressEl = document.getElementById("progressHit") || document.getElementById("progressTrack");
  const seek = ratio => {
    if (!audio || !isFinite(audio.duration)) return;
    audio.currentTime = ratio * audio.duration;
    document.getElementById("progressFill").setAttribute("width", 580 * ratio);
    document.getElementById("progressKnob").setAttribute("cx", 280 + 580 * ratio);
    document.getElementById("trackTime").textContent = formatTime(audio.currentTime) + " / " + formatTime(audio.duration);
  };
  bindDrag(progressEl, progressEl, seek);
  bindDrag(document.getElementById("progressKnob"), progressEl, seek);
  const volBox = document.getElementById("volHit") || document.getElementById("volTrack");
  const setVol = ratio => { volume = ratio; paintVolume(); };
  bindDrag(volBox, volBox, setVol);
  bindDrag(document.getElementById("volKnob"), volBox, setVol);
  paintVolume();
}

bindSliders();
setTimeout(init, 40);
